    FLAG = 4

class Portfolio:
    def __init__(self, key) -> None:
        self.key = key
        self.balance = 2000.00
        self.portfolio = defaultdict(int)
        self.requests = 0

    def bkup(key, portfolio, balance, requests):
        ret = Portfolio(key)
        ret.key = key
        ret.balance = balance
        ret.requests = requests
        ret.portfolio = portfolio.copy()
        return ret

    def status(self) -> dict:
        return {
