    #sanity check
    print(key, action, stock, stock1, stock in COMPANIES.keys(), stock1 in COMPANIES.keys())
    if (stock != "flag" and stock not in COMPANIES.keys()) or (stock1 != None and stock1 not in COMPANIES.keys()):
